import csv

def process_csv_chunks(filepath, chunk_size=1000):
    chunk = []
    with open(filepath) as f:
        reader = csv.DictReader(f)
        for row in reader:
            chunk.append(row)
            if len(chunk) >= chunk_size:
                yield chunk
                chunk = []
        if chunk:
            yield chunk

for rows in process_csv_chunks("data.csv"):
    save_to_db(rows)
