def pipe(*functions):
    def piped(value):
        for func in functions:
            value = func(value)
        return value
    return piped

def uppercase(data):
    return [{**row, "name": row["name"].upper()} for row in data]

def filter_by_amount(threshold):
    def filter_func(data):
        return [row for row in data if row["amount"] > threshold]
    return filter_func

process = pipe(uppercase, filter_by_amount(100))
result = process(data)
